def page(title,body,home='../START_HERE.html'):
 return f'''<!doctype html><html lang="zh-Hant-TW"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{html.escape(title)}｜程式如何變成影片</title><link rel="stylesheet" href="site.css"></head><body><div class="shell"><header class="top"><a class="brand" href="{home}">程式如何變成影片</a><span class="pill">寫書交接包 · V1</span></header>{body}<footer class="footer">李詩民的原理學習書專案 · 2026-10-05<br>本頁是交接資料，不代表全書已完成。所有核心檔案均保留可編輯文字版本。</footer></div></body></html>'''
for infile,outfile,title in [('SAMPLE_CHAPTER/CH04_圓點為什麼會動.md','sample_chapter.html','第四章校準樣章'),('OUTLINE/FULL_BOOK_OUTLINE.md','outline.html','六部二十四章完整目錄')]:
 body='<article class="article">'+md((r/infile).read_text(encoding='utf-8'))+'</article>'
 if infile.startswith('OUTLINE/'):
  body=body.replace('href="CHAPTER_BRIEFS/', 'href="../OUTLINE/CHAPTER_BRIEFS/')
 (read/outfile).write_text(page(title,body),encoding='utf-8')
